let
    Demo = Binary.Decompress(Binary.FromText("", BinaryEncoding.Base64), Compression.Deflate),
    Source = if DataMode = "Demo" then Demo else if DataMode = "Folder" then File.Contents(DataFolder & "/Opportunities.csv") else error "DataMode must be Demo or Folder",
    Parsed = Csv.Document(Source, [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    Headers = Table.PromoteHeaders(Parsed, [PromoteAllScalars=true]),
    Typed = Table.TransformColumnTypes(Headers, {{"OpportunityID", type text}, {"OwnerID", type text}, {"Source", type text}, {"Stage", type text}, {"CreatedDate", type date}, {"ClosedDate", type date}, {"LastActivityDate", type date}, {"Amount", Currency.Type}, {"Probability", Currency.Type}, {"CycleDays", Int64.Type}, {"IsOpen", Int64.Type}}, "en-US")
in
    Typed
